import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";import"./chunks/assets.ClIvgOmH.js";var i=JSON.parse(`{"title":"Jevの接続設定と利用状況","description":"","frontmatter":{},"headers":[],"relativePath":"guides/jev.md","filePath":"guides/jev.md","lastUpdated":1793607638000}`),a={name:`guides/jev.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="jevの接続設定と利用状況" tabindex="-1">Jevの接続設定と利用状況 <a class="header-anchor" href="#jevの接続設定と利用状況" aria-label="Permalink to “Jevの接続設定と利用状況”">​</a></h1><p>対象サイトを選び、左メニューの「Jev連携」を開きます。サイト管理者とSuperuserだけが利用できます。編集者・閲覧者にはキー設定・利用記録を公開しません。</p><h2 id="サイトごとのキーを設定する" tabindex="-1">サイトごとのキーを設定する <a class="header-anchor" href="#サイトごとのキーを設定する" aria-label="Permalink to “サイトごとのキーを設定する”">​</a></h2><p>「接続設定」で、次のいずれかを選びます。</p><table tabindex="0"><thead><tr><th>使用するキー</th><th>動作</th></tr></thead><tbody><tr><td>インスタンス共通キー</td><td>環境管理者がSecretとして設定したJEV_API_KEYを使う</td></tr><tr><td>サイト専用キー</td><td>このサイトに保存したJevキーを使う</td></tr><tr><td>Jevの利用を停止</td><td>通常のJev判断を保留する</td></tr></tbody></table><p>既存サイトも新規サイトも初期状態では共通キーです。サイト専用キーだけを運用する場合は、共通キーを設定せず、各サイトへ個別に登録できます。</p><ol><li>「サイト専用キー」を選ぶ。</li><li>「新しいサイト専用APIキー」へ入力する。</li><li>「Jev接続設定を保存」を押して確認する。必要に応じてパスキーで本人確認する。</li></ol><p>保存済みの値は再表示しません。再度開くと空欄になり、「保存済み」とだけ表示されます。既に専用キーがある場合、空欄で保存すると現在値を保持します。新しい値を入力すると置き換わります。保存操作ではJevへの接続・有効性確認・課金を行いません。</p><p>専用キーの保存には、環境管理者による<a href="./../operations/jev-keys">暗号化キーの初期設定</a>が必要です。未設定の場合は案内が表示されます。</p><div class="warning custom-block"><p class="custom-block-title">接続モードの切り替え</p><p>共通キーまたは利用停止へ変更すると、保存済みサイトキーを削除します。元に戻す場合はキーを入力し直してください。Jev側のキーを失効する操作ではありません。</p></div><p>サイト専用キーが失効・復号不能でも、共通キーへ自動では戻りません。保留になり、別のキーに意図せず課金しません。キー変更前から進行している要求は取り消せません。</p><p>以下はテスト用の設定による画面例です。実際のAPIキーは表示していません。</p><p><img src="/jev-personalization/images/jev-connection.png" alt="サイト専用キーの接続設定" width="1280" height="896"></p><h2 id="利用状況を見る" tabindex="-1">利用状況を見る <a class="header-anchor" href="#利用状況を見る" aria-label="Permalink to “利用状況を見る”">​</a></h2><p>「利用状況」を開き、過去7日・30日・90日を選んで「更新」を押します。集計はUTC日単位です。日別件数と最近100件の結果・モデル名・HTTP status・遅延・キーの種類を表示します。キーの変更前後を含むこのサイト全体の記録です。自動ポーリングは行いません。</p><table tabindex="0"><thead><tr><th>表示</th><th>意味</th></tr></thead><tbody><tr><td>呼び出し開始</td><td>Jev APIの呼び出し開始処理を記録した数</td></tr><tr><td>正常応答</td><td>HTTPの応答と基本的なデータ形式が正常だった数。表示条件に合致した数ではない</td></tr><tr><td>エラー</td><td>HTTP失敗・タイムアウト・通信失敗・応答形式不正</td></tr><tr><td>結果未確定</td><td>処理中・処理の中断・結果の保存失敗のいずれかで、結果が確定していない記録</td></tr></tbody></table><p>ブラウザからの判断要求がすべてJevへ進むわけではありません。条件未達、予算超過、キー未設定、停止、Preview/local-reviewの固定判定、配信前の強制プレビューは件数に含みません。新機能を導入する前の履歴も表示しません。</p><p>画面例の件数・結果・モデル・遅延は、UI検証用に作成した人工データです。Jevの実測ではありません。</p><p><img src="/jev-personalization/images/jev-usage.png" alt="Jev利用状況の画面例" width="1280" height="1306"></p><h2 id="件数と課金の違い" tabindex="-1">件数と課金の違い <a class="header-anchor" href="#件数と課金の違い" aria-label="Permalink to “件数と課金の違い”">​</a></h2><p>送信開始前に記録し、応答後に結果を更新します。その間の中断では、実際の送信前でも開始行が残ったり、送信済みでも未確定になったりします。Jev側が受信した件数・課金件数・金額を保証するカウンターではありません。</p><p><strong>課金や消費量はJev（TypeSafe）側で確認してください。</strong> 失敗した要求の課金有無も提供元のルールに従います。正常応答は購入・施策成功を意味せず、遅延はJevのHTTP処理時間で、画面表示までの全時間ではありません。</p><p>費用上限と同時実行数は、専用キーを使う場合もインスタンス全体で共有します。サイト別の予算上限は今回の機能に含みません。</p><h2 id="記録されないもの" tabindex="-1">記録されないもの <a class="header-anchor" href="#記録されないもの" aria-label="Permalink to “記録されないもの”">​</a></h2><p>キーの値・断片、閲覧者ID・IP・URL・履歴、state、questions、回答、確率、要求/応答本文は残しません。保存対象は呼び出しの運用メタデータだけです。記録は最大90日の範囲で表示し、古い行は利用・閲覧のタイミングで削除します。バックアップ中の記録は別の保持方針で管理します。</p><p>Previewの固定判定では、キーを入力しても実際の有効性やJevとの接続は確認できず、利用件数は増えません。実接続を試す場合は環境管理者と確認し、課金される要求として別途実施してください。</p>`,26)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};